"""Original Saltwake Eulogist action references, fixed anatomical registration."""
import json
from PIL import Image
import produce as p
UID='unit_veilmourn_saltwake_eulogists'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original SALTWAKE EULOGIST from the supplied painting. One slender humanoid mourner facing SCREEN RIGHT in original blue-and-ivory layered mourning robes, ragged translucent blue sails, pale masked face and bony crown. Exactly TWO arms and TWO legs. The original near hand grips ONE long dark bronze staff with exactly THREE tall pale blue saltglass cylinders at its top, ornate bronze crown, and one lower hanging pale-blue lantern. Preserve the staff shaft length, three-cylinder arrangement and correct single grip. The original far hand is the open casting hand; no extra arms, fingers, staffs, shields or weapons. Original belt scrolls and ornaments remain attached. Painted fantasy game artwork, unchanged body scale, proportions and camera. ')
PLATE=(' Entire backdrop flat magenta RGB255,0,255 throughout; no scenery, floor, cast shadow, text, camera movement, zoom or cuts. Keep all legitimate staff tips, robe ribbons and limbs within ample canvas margins. Fixed boot contact plane y576; actual steps lift boots but planted boots do not slide. Preserve the original pale blue robes and saltglass without recoloring or enlarging effects. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if index==14:f['anchor']=[1260,566]
 if index==15:f['anchor']=[292,905]
 if index==17:f['anchor']=[1280,920]
 return f

def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[0,2,3,5],[[30,1],[60,2],[90,3]],0,'One complete reciprocal walking cycle IN PLACE. The near boot steps forward and plants while the far boot trails, then far boot passes and steps forward as near boot trails. Knees and hips articulate below the robe. Staff stays upright in the same near-hand grip; free far arm balances the gait. Robe and sails follow weight shifts without stretching. No sideways root travel or added legs. Return smoothly to exact initial ready. ',2026108201)
 recipe('attack',[0,6,7],[[32,1],[65,2]],0,'One physical staff strike SCREEN RIGHT: take the free far hand onto the shaft as the original near hand retains its grip; wind up the single staff diagonally back, thrust the same bronze staff crown forward once to contact, draw it back and recover to exact ready. Exactly two hands, no split staff, bending shaft, projectile, magic flare or repeated strikes. ',2026108202)
 recipe('ranged',[0,11,12],[[32,1],[65,2]],0,'One ranged Saltglass cast SCREEN RIGHT. Staff stays upright in the same near-hand grip, all three blue cylinders unchanged. Far free hand draws toward the chest, then extends palm forward deliberately and releases a small pale blue saltglass wisp at the fingertips, matching the original release pose. The game adds projectile flight; do not emit a detached travelling projectile, beam or large cloud. One release, then free hand returns and recover to exact ready. ',2026108203)
 recipe('hit',[0,13],[[45,1]],0,'One brief impact recoil. Both boots brace, chest leans back, masked head flinches and free far forearm crosses toward chest; original near hand keeps the single three-cylinder staff upright. Robe sails react gently. Recover smoothly to exact ready, no collapse or turning away. ',2026108204)
 recipe('defend',[0,10],[],1,'One continuous defensive brace: lower into a bent-knee stance, incline the single original staff diagonally above the shoulder, bring the free far forearm over the brow as the head ducks. Keep both boots grounded and hold the compact original guard for the final second. Staff remains one rigid three-cylinder staff, no new props or return to ready. ',2026108205)
 recipe('cast',[0,11],[[50,1]],0,'One distinct supportive obituary gesture. Staff remains upright in the original near-hand grip. Free far hand draws inward across the chest, lifts palm slowly near the face in a mourning salutation, head bows, then hand lowers and returns to ready. Robe sails respond naturally. This is deliberate close-body support, not the forward ranged release. No new props, scroll duplication or projectile. ',2026108206)
 recipe('death',[0,14,15,17],[[38,1],[78,2]],3,'One continuous grounded collapse. Knees buckle, the body sinks to kneeling, then torso and head fall SCREEN RIGHT into the supplied original side-lying corpse. The near hand retains the same single staff as it descends to lie beside the body; far arm folds naturally. Exactly two arms and two legs, no standing back up, shrinking or disintegration. Robe and sails settle after landing. Finish with body and staff fully grounded, last second motionless. ',2026108207)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='All26 original poses personally inspected. Existing idle18-25 has clear free-hand articulated salutation and returning loop; preserve exact original pixels and240ms timing. Seven H3 actions require chronological/enlarged/native review.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,640],ground_anchor=[480,576],ready_guide=reference(0),corpse_guide=reference(17),reason='Original per-source anatomical scales retained; fixed extraction scale and boot contact plane, no per-frame normalization.'))
